\"\"\"Revenue per store day. See docs/store-days.md.\"\"\"

from datetime import datetime, timedelta, timezone
import re

from shoplib.errors import ShopError


def daily_revenue(sales: list[dict], utc_offset_hours: int = 8, day_starts_hour: int = 4) -> list[tuple[str, int]]:
    \"\"\"Return totals for each store day between the first and last sale.\"\"\"
    if type(utc_offset_hours) is not int or not -23 <= utc_offset_hours <= 23:
        raise ShopError(\"invalid UTC offset\")
    if type(day_starts_hour) is not int or not 0 <= day_starts_hour <= 23:
        raise ShopError(\"invalid day start hour\")

    local_zone = timezone(timedelta(hours=utc_offset_hours))
    totals = {}
    for sale in sales:
        if not isinstance(sale, dict) or not isinstance(sale.get(\"at\"), str) or type(sale.get(\"cents\")) is not int:
            raise ShopError(\"invalid sale\")
        timestamp = sale[\"at\"]
        if not re.search(r\"(?:Z|[+-]\\d{2}:\\d{2})"'$", timestamp):
            raise ShopError("timestamp must include a time zone")
        try:
            local = datetime.fromisoformat(timestamp).astimezone(local_zone)
            day = local.date()
            if local.hour < day_starts_hour:
                day -= timedelta(days=1)
        except (ValueError, OverflowError) as exc:
            raise ShopError("invalid timestamp") from exc
        totals[day] = totals.get(day, 0) + sale["cents"]

    if not totals:
        return []
    day, last = min(totals), max(totals)
    result = []
    while True:
        result.append((day.isoformat(), totals.get(day, 0)))
        if day == last:
            return result
        day += timedelta(days=1)
EOF
cat > tests/test_storedays.py <<'"'EOF'
import pytest

from shoplib.errors import ShopError
from shoplib.storedays import daily_revenue


def test_boundaries_offsets_refunds_and_gaps():
    sales = [
        {\"at\": \"2026-11-18T02:30:00+08:00\", \"cents\": 100},
        {\"at\": \"2026-11-17T20:00:00Z\", \"cents\": 200},
        {\"at\": \"2026-11-18T04:00:00+08:00\", \"cents\": -50},
        {\"at\": \"2026-11-21T00:00:00-04:00\", \"cents\": 75},
    ]
    assert daily_revenue(sales) == [
        (\"2026-11-17\", 100),
        (\"2026-11-18\", 150),
        (\"2026-11-19\", 0),
        (\"2026-11-20\", 0),
        (\"2026-11-21\", 75),
    ]


def test_custom_timezone_and_start_across_year():
    sales = [
        {\"at\": \"2027-01-01T04:59:59Z\", \"cents\": 1},
        {\"at\": \"2027-01-01T05:00:00Z\", \"cents\": 2},
    ]
    assert daily_revenue(sales, utc_offset_hours=-5, day_starts_hour=0) == [
        (\"2026-12-31\", 1), (\"2027-01-01\", 2)
    ]
    assert daily_revenue([]) == []


@pytest.mark.parametrize(\"timestamp\", [\"2026-11-18T02:30:00\", \"invalidZ\"])
def test_invalid_timestamp_raises_shop_error(timestamp):
    with pytest.raises(ShopError):
        daily_revenue([{\"at\": timestamp, \"cents\": 1}])


@pytest.mark.parametrize(\"kwargs\", [{\"utc_offset_hours\": 24}, {\"day_starts_hour\": 24}])
def test_invalid_configuration(kwargs):
    with pytest.raises(ShopError):
        daily_revenue([], **kwargs)
EOF
